import React, { useEffect, useState } from "react";
import axios from "axios";
import { Html5QrcodeScanner } from "html5-qrcode";
import { useNavigate } from "react-router-dom";

function QRScanner() {

const [user,setUser] = useState(null);
const [message,setMessage] = useState("");

const navigate = useNavigate();

useEffect(()=>{

const admin = localStorage.getItem("admin");

if(!admin){
alert("Please login as Admin");
navigate("/admin-login");
return;
}

/* START SCANNER */

const scanner = new Html5QrcodeScanner(
"reader",
{
fps:10,
qrbox:250
},
false
);

scanner.render(
(decodedText)=>{

console.log("QR SCANNED:",decodedText);

verifyUser(decodedText);

},
(error)=>{
// ignore scan errors
}
);

/* CLEANUP */

return ()=>{
try{
scanner.clear();
}catch(err){
console.log("Scanner already cleared");
}
};

},[navigate]);

/* VERIFY USER */

const verifyUser = async(id)=>{

try{

const res = await axios.get(
`http://localhost:5000/verify-user/${id}`
);

if(res.data.success){

setUser(res.data.user);

setMessage("✅ VERIFIED - Attendance Marked");

await axios.put(
`http://localhost:5000/mark-attendance/${id}`
);

}else{

setUser(null);

setMessage("❌ NOT REGISTERED");

}

}catch(error){

console.log(error);

setMessage("⚠️ SERVER ERROR");

}

};

return(

<div style={{padding:"20px"}}>

<h2>Admin QR Scanner</h2>

<div id="reader" style={{width:"320px"}}></div>

<h3>{message}</h3>

{user && (

<div style={{
border:"1px solid #ccc",
padding:"10px",
marginTop:"10px"
}}>

<p><b>Name:</b> {user.name}</p>
<p><b>College:</b> {user.college_name}</p>
<p><b>Phone:</b> {user.phone}</p>
<p><b>Event:</b> {user.event_id}</p>

</div>

)}

</div>

);

}

export default QRScanner;
